# Our search for key that gives Enc(0)=b0 failed for MD5-based keys. So IV is not zero.
# Could be that key is MD5 and IV is derived from password via some other method, and we just need to find IV derivation.

# Let's attempt to see if IV could be MD5 of password reversed, or MD5 of password + constant string like "caps-log" but we tried some.

# Let's brute force IV = MD5( password + salt ) where salt is from a list of common words, and see if matches IV_scratch.

import hashlib

def md5(s):
    return hashlib.md5(s.encode()).hexdigest()

salts = ["", "0", "1", "2", "salt", "caps-log", "caps-log-encrypted", "encrypted", "iv", "scratch", "scratchpads", "a.md", "123", "abc", "password", "key", "aes", "ofb", "cfb", "16", "0000000000000000", "0"*16, "1"*16]

# Also try with password + salt in different orders: salt+pwd, pwd+salt, salt+pwd+salt

for pwd, iv in [("a","cec520ea51ea0a47e87295fa3245a605"), ("mypass","a10ce9c4682486f8622f2f18e7291367")]:
    print(f"\nTrying to match IV for pwd {pwd} iv {iv}")
    for salt in salts:
        for combo in [pwd+salt, salt+pwd, salt+pwd+salt, pwd+salt+pwd]:
            if md5(combo)==iv:
                print(f"FOUND MD5({combo!r}) == {iv}")
